  "rust",
  "use hugr_omni::Command;",
  "#[tokio::main]",
  "async fn main() -> Result<(), hugr_omni::Error> {",
  '    let out = Command::new("node").args(["--version"]).run().await?;',
  "    assert!(out.exit.success());",
  "    Ok(())",
  "}",
);

