test("run: a pid file that is not a pid cannot be proven gone, and fails", () => {
  const writes = fence("ts", 'const { writeFileSync } = await import("node:fs" as string);', 'writeFileSync("dev.pid", "banana");');
  expects(real(writes), 1, "cannot be proven that it left nothing running", "dev.pid (not a pid)");
});

test("survivors: a pid the inspection cannot answer for, or that is not a pid, is not proven gone", () => {
  const dir = tree({ "a.pid": "4242\n", "b.pid": "banana\n", "c.pid": "0\n" });
  const got = survivors(dir, () => {
    throw new Error("boom");
  });
  assert.deepEqual(got.running, []);
  assert.equal(got.unknown.length, 3, JSON.stringify(got));
  assert.ok(got.unknown.some((u) => u.includes("pid 4242: cannot be inspected: boom")), JSON.stringify(got));
  assert.ok(got.unknown.some((u) => u.includes("b.pid (not a pid)")) && got.unknown.some((u) => u.includes("c.pid (not a pid)")), JSON.stringify(got));
});

test("isAlive: a reaped pid is gone and this process is alive", () => {
  const reaped = spawnSync(process.execPath, ["-e", "0"]).pid;
  assert.equal(isAlive(reaped), false);
  assert.equal(isAlive(process.pid), true);
});

/** The `stat` of `pid` as `ps` prints it (empty when there is no such process). */
const stat = (pid) => spawnSync("ps", ["-o", "stat=", "-p", String(pid)], { encoding: "utf8" }).stdout.trim();

test("survivors: a zombie is not a leak, a live process is", { skip: process.platform === "win32" && "Windows has no zombies" }, async () => {
  // `sh` forks `sleep 0`, then becomes `sleep 30`, which never reaps it: an exited, unreaped child.
  const parent = spawn("sh", ["-c", "sleep 0 & echo $!; exec sleep 30"], { stdio: ["ignore", "pipe", "ignore"] });
  try {
    const zombie = Number(await new Promise((resolve) => parent.stdout.once("data", (d) => resolve(String(d).trim()))));
    const deadline = Date.now() + 10_000;
    while (!stat(zombie).startsWith("Z")) {
      assert.ok(Date.now() < deadline, `pid ${zombie} never became a zombie (stat "${stat(zombie)}")`);
      await new Promise((r) => setTimeout(r, 20));
    }
    assert.doesNotThrow(() => process.kill(zombie, 0), "kill(pid, 0) succeeds on a zombie: the false leak this guards against");
    assert.equal(isAlive(zombie), false);
    const dir = tree({ "zombie.pid": `${zombie}\n` });
    assert.deepEqual(survivors(dir), { running: [], unknown: [] });
    writeFileSync(join(dir, "live.pid"), `${parent.pid}\n`);
    const got = survivors(dir);
    assert.deepEqual(got.unknown, []);
    assert.equal(got.running.length, 1, JSON.stringify(got));
    assert.ok(got.running[0].includes(`pid ${parent.pid}`), JSON.stringify(got));
  } finally {
    parent.kill("SIGKILL");
  }
});

export function isAlive(pid) {
  if (process.platform === "win32") {
    const r = spawnSync("tasklist", ["/FI", `PID eq ${pid}`, "/FO", "CSV", "/NH"], { encoding: "utf8" });
    if (r.error || r.status !== 0) throw new Error(`tasklist failed (${r.error?.code ?? r.status}): ${r.stderr.trim()}`);
    return r.stdout.split("\n").some((row) => row.split(",")[1]?.replaceAll('"', "").trim() === String(pid));
  }
  if (process.platform === "linux") {
    let stat;
    try {
      stat = readFileSync(`/proc/${pid}/stat`, "utf8");
    } catch (e) {
      if (e.code === "ENOENT" || e.code === "ESRCH") return false;
      throw new Error(`/proc/${pid}/stat cannot be read (${e.code ?? e.message})`);
    }
    const state = stat.slice(stat.lastIndexOf(")") + 2).split(" ")[0];
    if (!/^[A-Za-z]$/.test(state)) throw new Error(`/proc/${pid}/stat has no state: ${stat.slice(0, 60)}`);
    return state !== "Z" && state !== "X";
  }
  const r = spawnSync("ps", ["-o", "stat=", "-p", String(pid)], { encoding: "utf8" });
  if (r.error) throw new Error(`ps cannot be started (${r.error.code ?? r.error.message})`);
  const state = r.stdout.trim();
  if (r.status === 1 && state === "" && r.stderr.trim() === "") return false; // ps: no such process
  if (r.status !== 0 || state === "") throw new Error(`ps failed (${r.status}): ${r.stderr.trim() || "no state"}`);
  return !state.startsWith("Z");

export function survivors(dir, alive = isAlive) {
  const running = [];
  const unknown = [];
  for (const name of readdirSync(dir).filter((n) => n.endsWith(".pid"))) {
    const pid = Number(readFileSync(join(dir, name), "utf8").trim());
    if (!Number.isInteger(pid) || pid <= 1) {
      unknown.push(`${name} (not a pid)`); // never signal 0 or 1: that reaches a whole group
      continue;
    }
    let live;
    try {
      live = alive(pid);
    } catch (e) {
      unknown.push(`${name} (pid ${pid}: cannot be inspected: ${e.message})`);
      continue;
    }
    if (!live) continue;
    running.push(`${name} (pid ${pid})`);
    try {
      process.kill(pid);
    } catch {
      // gone in between
    }
  }
  return { running, unknown };
}

/** Runs `cmd` in `cwd` for one `ts` or `rust` block; returns a violation text or null. `hint` is appended to a failure. */
function execute(block, cmd, args, cwd, env, ms, hint = "") {
  const where = `${block.file}:${block.line}`;
  const r = sh(cmd, args, { cwd, env, timeout: ms, killSignal: "SIGKILL" });
  const { running, unknown } = survivors(cwd);
  if (r.error?.code === "ETIMEDOUT") return `${where}: the ${block.lang} block did not finish in ${ms} ms (a hang is a failure)${hint}`;
  if (r.status !== 0) return `${where}: the ${block.lang} block exited ${r.status ?? r.signal}\n${tail(`${r.stdout}\n${r.stderr}`)}${hint}`;
  if (unknown.length > 0) return `${where}: the block ended, but it cannot be proven that it left nothing running: ${unknown.join(", ")}`;
  if (running.length > 0) return `${where}: the block ended but left running: ${running.join(", ")} (its tree was not stopped)`;

function runRust(blocks, work, env, ms, repo) {
  const out = [];
  const target = process.env.CARGO_TARGET_DIR ?? join(repo, "target");
  const supervisor = join(work, "target", "release", `hugr-omni-supervisor${EXE}`); // built by the README's `sh` block
  const runEnv = { ...env };
  delete runEnv.HUGR_OMNI_SUPERVISOR;
  blocks.forEach((b, i) => {
    const project = join(work, `r${i}`);
    cpSync(fixture, project, { recursive: true });
    const crate = join(work, `crate${i}`);
    mkdirSync(join(crate, "src"), { recursive: true });
    writeFileSync(join(crate, "src", "main.rs"), `${b.code}\n`);
    // The dependencies are the README's own `toml` block; the only change is hugr-omni's git URL, swapped for this checkout.
    const deps = b.deps.replace(/(^[ \t]*hugr-omni\s*=\s*\{[^}\n]*?)\bgit\s*=\s*"[^"\n]+"/m, `$1path = "${fwd(join(repo, "crates", "hugr-omni"))}"`);
    if (deps === b.deps) throw new Unrunnable(`${b.file}:${b.line}: the toml block before the rust block has no hugr-omni git dependency to point at this checkout`);
    writeFileSync(
      join(crate, "Cargo.toml"),
      `[package]\nname = "readme-block-${i}"\nversion = "0.0.0"\nedition = "2024"\npublish = false\n\n${deps.trim()}\n\n[workspace]\n`,
    );
    cpSync(join(repo, "Cargo.lock"), join(crate, "Cargo.lock"));
    // cwd = the repository, so rustup picks its rust-toolchain.toml; the crate is found by --manifest-path.
    const built = sh("cargo", ["build", "--quiet", "--manifest-path", join(crate, "Cargo.toml")], {
      cwd: repo, env: { ...runEnv, CARGO_TARGET_DIR: target }, timeout: 1_800_000,
    });
    if (built.status !== 0) {
      out.push(`${b.file}:${b.line}: the rust block does not build\n${tail(`${built.stdout}\n${built.stderr}`)}`);
      return;
    }
    // Next to its own copy of the executable, as the README says, and nowhere else: not the debug supervisor in target/.
    const bin = join(work, `bin${i}`);
    mkdirSync(bin);
    const exe = join(bin, `readme-block-${i}${EXE}`);
    copyFileSync(join(target, "debug", `readme-block-${i}${EXE}`), exe);
    const placed = existsSync(supervisor);
    if (placed) copyFileSync(supervisor, join(bin, `hugr-omni-supervisor${EXE}`));
    const hint = placed ? "" : "\n(no sh block of the docs built target/release/hugr-omni-supervisor, which the Rust example needs: cargo build --release -p omni-supervisor)";
    const failure = execute(b, exe, [], project, runEnv, ms, hint);
    if (failure) out.push(failure);

/** Runs every block it is given (`sh`, `ts`, `rust`); returns the violations. Throws `Unrunnable` when a tool or build is missing. */
export function runBlocks(blocks, { repo, timeoutMs, cache }) {
  const work = mkdtempSync(join(tmpdir(), "readme-check-"));
  try {
    const pick = (lang) => blocks.filter((b) => b.lang === lang);
    const out = [];
    if (pick("sh").length) out.push(...runSh(pick("sh"), work, process.env, timeoutMs, repo));
    if (pick("ts").length) out.push(...runTs(pick("ts"), work, process.env, timeoutMs, repo, cache));
    if (pick("rust").length) out.push(...runRust(pick("rust"), work, process.env, timeoutMs, repo));
    return out;
  } finally {
    try {
      rmSync(work, { recursive: true, force: true, maxRetries: 5, retryDelay: 200 });
    } catch {
      // a temp directory some process still holds (Windows) is not worth failing the run for
    }

// Per skill folder (every entry of skills/ must be one):
//   - SKILL.md opens with frontmatter (markdown.mjs reads it): `name` equals the folder and matches [a-z0-9-]{1,64};
//     `description` is at most 1024 characters, holds "Use when" (it is the trigger text) and no `<` or `>`; no key
//     outside KEYS; the body is at most 500 lines and has the headings "## When to use" and "## When not to use";
//   - the folder holds SKILL.md and, optionally, references/: .md files only, no subfolder (references stay one
//     level deep), each one linked from SKILL.md.
// Per file (SKILL.md and its references):
//   - every relative link resolves to a file or folder inside this package (the mirror holds nothing else), and every
//     `#anchor` to a heading of the .md file it names (or of the file itself);
//   - every inline code span that is, or starts with (followed by `:`, `(` or `=`), an identifier of one of two shapes
//     is checked against bindings/node/index.d.ts (read with surface-check/dts.mjs):
//       option shape  lowerCamelCase with at least one hump (`timeoutMs`, `droppedBytes`): a name of the surface;
//       code shape    upper case with two letters or more, `_` allowed (`NOT_FOUND`, `IO`): an `OmniError` code;
//     anything else (a dotted path, a lower-case word, a sentence, fenced code) is not looked at. A shaped identifier
//     that is not omni's (`PATH`, `killSignal`) must be listed in FOREIGN, one per line with a `# why`; an entry that
//     omni does have, that no skill uses, or that is listed twice is a violation (the ledger cannot rot).
// Plus .claude-plugin/plugin.json: valid JSON with a kebab-case `name`; any `skills` path it adds exists.
//
//   node scripts/skill-check/check.mjs [--root <package root>]
// Exit: 0 holds · 1 violations (each names file:line) · 2 an input cannot be read (no skill at all, no index.d.ts,
// no OmniError codes, no ledger), or an argument is unknown.

/** Checks the links, anchors and identifiers of one file (`path` relative to `root`); `used` collects foreign ids met. */
function checkFile(root, path, lines, first, known, foreign, used) {
  const out = [];
  const found = scan(lines, first);
  if (found.unclosed) out.push(`${path}: a code fence is never closed (the rest of the file would be read as code)`);
  const linked = [];
  for (const { line, value } of found.links) {
    if (/^[a-z][a-z0-9+.-]*:/i.test(value)) continue; // http:, https:, mailto:
    const where = `${path}:${line}`;
    const [target, anchor] = value.split("#", 2);
    const file = target === "" ? join(root, path) : resolve(join(root, dirname(path)), decodeURI(target));
    const rel = relative(root, file);
    if (rel.startsWith("..") || isAbsolute(rel)) {
      out.push(`${where}: the link \`${value}\` leaves this package (the mirror would not have it)`);
      continue;
    }
    const k = kind(file);
    if (k === null) {
      out.push(`${where}: the link \`${value}\` names ${rel}, which does not exist`);
      continue;
    }
    linked.push(rel.split("\\").join("/"));
    if (anchor === undefined) continue;
    if (k !== "file" || !file.endsWith(".md")) {
      out.push(`${where}: the link \`${value}\` has an anchor, but ${rel} is not a Markdown file`);
      continue;
    }
    const anchors = target === "" ? found.anchors : scan(readFileSync(file, "utf8").replace(/\r\n/g, "\n").split("\n")).anchors;
    if (!anchors.has(anchor)) out.push(`${where}: ${rel} has no heading with the anchor #${anchor}`);
  }
  let checked = 0;
  for (const { line, value } of found.spans) {
    const id = /^([A-Za-z_$][\w$]*)(?:$|[:(=])/.exec(value)?.[1];
    if (!id) continue;
    const option = OPTION.test(id);
    const code = CODE.test(id);
    if (!option && !code) continue;
    checked++;
    if (foreign.has(id)) {
      used.add(id);
      continue;
    }
    if (option && !known.names.has(id)) out.push(`${path}:${line}: \`${id}\` is not a name of ${DTS} (a renamed or invented option?); if it is another library's, list it in ${FOREIGN}`);
    if (code && !known.codes.has(id)) out.push(`${path}:${line}: \`${id}\` is not an \`OmniError\` code of ${DTS}; if it is another name (an env var, a signal), list it in ${FOREIGN}`);

const path = `${dir}/SKILL.md`;
const fm = frontmatter(read(root, path));
out.push(...fm.problems.map((p) => `${path}${p.replace(/^line (\d+): /, ":$1: ").replace(/^(?!:)/, ": ")}`));
if (fm.fields) {
  for (const [key, { line }] of fm.fields) if (!KEYS.has(key)) out.push(`${path}:${line}: unknown frontmatter key \`${key}\` (known: ${[...KEYS].join(", ")})`);
  const n = fm.fields.get("name");
  if (!n) out.push(`${path}: the frontmatter has no \`name\``);
  else {
    if (!/^[a-z0-9-]{1,64}$/.test(n.value)) out.push(`${path}:${n.line}: name "${n.value}" must match [a-z0-9-]{1,64}`);
    if (n.value !== name) out.push(`${path}:${n.line}: name "${n.value}" is not the folder's name "${name}"`);
  }
  const d = fm.fields.get("description");
  if (!d || d.value.trim() === "") out.push(`${path}: the frontmatter has no \`description\` (the text that triggers the skill)`);
  else {
    if (d.value.length > MAX_DESCRIPTION) out.push(`${path}:${d.line}: the description has ${d.value.length} characters; the limit is ${MAX_DESCRIPTION}`);
    if (!d.value.includes("Use when")) out.push(`${path}:${d.line}: the description must say "Use when ..." (it is the trigger text)`);
    if (/[<>]/.test(d.value)) out.push(`${path}:${d.line}: the description must not contain < or >`);
  }
}
if (fm.body.length > MAX_BODY) out.push(`${path}: the body has ${fm.body.length} lines; the limit is ${MAX_BODY} (move detail to references/)`);
for (const h of HEADINGS) if (!fm.body.some((l) => l.trimEnd() === h)) out.push(`${path}: has no "${h}" heading`);

const skill = take(checkFile(root, path, fm.body, fm.bodyLine, known, foreign, used));
for (const ref of refs) {
  take(checkFile(root, ref, read(root, ref).replace(/\r\n/g, "\n").split("\n"), 1, known, foreign, used));
  if (!skill.linked.includes(ref)) out.push(`${ref}: no link from ${path} reaches it (a reference is read only through SKILL.md)`);

/** Runs every rule; returns `{ violations, summary }`. Throws `Unreadable` when an input cannot be read. */
export function check(root) {
  const known = surface(root);
  const { ids: foreign, out } = ledger(root, known);
  const used = new Set();
  const skills = entries(root, "skills");
  const totals = { files: 0, links: 0, checked: 0 };
  let n = 0;
  for (const e of skills) {
    if (!e.isDirectory()) {
      out.push(`skills/${e.name}: skills/ holds skill folders only`);
      continue;
    }
    n++;
    const r = checkSkill(root, e.name, known, foreign, used);
    out.push(...r.out);
    for (const k of Object.keys(totals)) totals[k] += r[k];
  }
  if (n === 0) throw new Unreadable("skills/: no skill folder found (the skills came back EMPTY)");
  for (const [id, line] of foreign) if (!used.has(id)) out.push(`${FOREIGN}:${line}: \`${id}\` is used by no skill; remove it`);
  out.push(...checkPlugin(root));
  const summary = `${n} skills, ${totals.files} files, ${totals.links} links, ${totals.checked} identifiers checked (${foreign.size} declared foreign)`;
  return { violations: out, summary };

test("the clean tree passes; fenced code, inline-code links, external links and plain words are not looked at", () => {
  expects(run(), 0, "OK", "2 skills", "1 declared foreign");
});

test("frontmatter: missing, unclosed, or a value YAML would read differently", () => {
  expects(run({ "skills/demo/SKILL.md": (t) => t.replace(/^---\n[\s\S]*?\n---\n/, "") }), 1, "skills/demo/SKILL.md", "no frontmatter");
  expects(run({ "skills/demo/SKILL.md": (t) => t.replace("\n---\n\n# Demo", "\n\n# Demo") }), 1, "never closed");
  expects(run({ "skills/other/SKILL.md": (t) => t.replace(`description: ${DESCRIPTION}`, "description: Use when: always") }), 1, "skills/other/SKILL.md:3", "quote it");
  expects(run({ "skills/other/SKILL.md": (t) => t.replace(`description: ${DESCRIPTION}`, "description: |\n  Use when x") }), 1, "YAML syntax", "not a one-line");
  expects(run(demo("name: demo\n", "name: demo\nname: demo\n")), 1, "`name` is given twice");
});

test("name: equal to the folder, and [a-z0-9-]{1,64}", () => {
  expects(run(demo("name: demo", "name: dem0")), 1, 'name "dem0" is not the folder\'s name "demo"');
  expects(run({ "skills/Bad_Name/SKILL.md": skill(`name: Bad_Name\ndescription: ${DESCRIPTION}`, "") }), 1, 'name "Bad_Name" must match');
  expects(run(demo("name: demo\n", "")), 1, "has no `name`");
});

test("description: present, at most 1024 characters, says Use when, no angle brackets", () => {
  expects(run(demo(`description: "${DESCRIPTION}"`, "")), 1, "has no `description`");
  expects(run(demo(DESCRIPTION, `${"x".repeat(1020)} Use when x`)), 1, "the limit is 1024");
  expects(run(demo("Use when", "Used when")), 1, 'must say "Use when');
  expects(run(demo("Runs things.", "Runs <things>.")), 1, "must not contain < or >");

test("a link to a missing file, a missing anchor, or outside the package fails and names it", () => {
  expects(run(demo("docs/guide.md#2-reading", "docs/guides.md#2-reading")), 1, "skills/demo/SKILL.md:19", "docs/guides.md, which does not exist");
  expects(run(demo("docs/guide.md#2-reading", "docs/guide.md#3-reading")), 1, "has no heading with the anchor #3-reading");
  expects(run(demo("(#map-1)", "(#map-2)")), 1, "skills/demo/SKILL.md has no heading with the anchor #map-2");
  expects(run(demo("(../../docs)", "(../../docs#x)")), 1, "is not a Markdown file");
  expects(run(demo("(../../docs)", "(../../../elsewhere.md)")), 1, "leaves this package");
  expects(run({ "skills/demo/references/more.md": (t) => t.replace("#when-to-use", "#when-to-run") }), 1, "skills/demo/references/more.md:3", "#when-to-run");
});

test("a fence never closed is reported (the rest of the file would be code)", () => {
  expects(run({ "skills/other/SKILL.md": (t) => `${t}\n\`\`\`ts\nconst x = 1;\n` }), 1, "never closed");
});

test("an option-shaped or code-shaped identifier omni does not have fails, unless declared foreign", () => {
  expects(run(demo("`timeoutMs`", "`timeoutMS`")), 1, "`timeoutMS` is not a name of bindings/node/index.d.ts");
  expects(run(demo("`inheritEnv: false`", "`inheritEnvs: false`")), 1, "`inheritEnvs` is not a name");
  expects(run(demo("`NOT_FOUND`", "`NOT_FUND`")), 1, "`NOT_FUND` is not an `OmniError` code");
  expects(run(demo("`killSignal`", "`killSignals`")), 1, "`killSignals` is not a name", "`killSignal` is used by no skill");
  expects(run({ "skills/demo/references/more.md": (t) => `${t}\nSee \`graceMS\`.\n` }), 1, "skills/demo/references/more.md:5", "`graceMS`");
});

test("the foreign ledger cannot rot: omni's own name, unused, duplicate, unshaped, or without a reason", () => {
  const ledger = (text) => ({ "scripts/skill-check/foreign.txt": (t) => `${t}${text}\n` });
  expects(run(ledger("timeoutMs   # mine")), 1, "`timeoutMs` is omni's own");
  expects(run(ledger("unusedThing   # nobody")), 1, "`unusedThing` is used by no skill");
  expects(run(ledger("killSignal   # again")), 1, "listed twice");
  expects(run(ledger("plain   # word")), 1, '"plain" has neither the option nor the code shape');
  expects(run({ "scripts/skill-check/foreign.txt": "killSignal\n" }), 1, "says no reason");
});

test("the skill folder: SKILL.md and references/ of .md files only, each reference linked", () => {
  expects(run({ "skills/demo/notes.txt": "x" }), 1, "skills/demo/notes.txt: a skill folder holds SKILL.md and references/ only");
  expects(run({ "skills/demo/references/deep/x.md": "# x\n" }), 1, "skills/demo/references/deep", "one level deep");
  expects(run({ "skills/demo/references/orphan.md": "# Orphan\n" }), 1, "skills/demo/references/orphan.md: no link from skills/demo/SKILL.md");
