test("an argument the check does not know, or --root without a directory, exits 2", () => {
  const root = tree();
  for (const args of [["--rot", root], ["--root"], ["--root", root, "--extra"], [root]]) {
    const got = run({}, [...args]);
    assert.equal(got.code, 2, `${args.join(" ")}: ${got.text}`);
    assert.ok(got.text.includes("unknown or incomplete arguments"), got.text);
  }

/** Splits `text` into `{ fields, body, bodyLine, problems }`; `bodyLine` is the 1-based line where the body starts. */
export function frontmatter(text) {
  const lines = text.replace(/\r\n/g, "\n").split("\n");
  const problems = [];
  if (lines[0] !== "---") return { fields: null, body: lines, bodyLine: 1, problems: ["line 1: no frontmatter (the file must start with a `---` line)"] };
  const end = lines.indexOf("---", 1);
  if (end < 0) return { fields: null, body: lines, bodyLine: 1, problems: ["the frontmatter is never closed (no second `---` line)"] };
  const fields = new Map();
  for (let i = 1; i < end; i++) {
    const raw = lines[i];
    if (raw.trim() === "") continue;
    const m = /^([a-z][a-z0-9-]*):(?: (.*))?$/.exec(raw);
    if (!m) {
      problems.push(`line ${i + 1}: "${raw.slice(0, 60)}" is not a one-line \`key: value\` (no YAML block, list, map or indented line is read)`);
      continue;
    }
    const [, key, given = ""] = m;
    const value = scalar(given.trim(), i + 1, problems);
    if (fields.has(key)) problems.push(`line ${i + 1}: \`${key}\` is given twice`);
    else fields.set(key, { value, line: i + 1 });
  }
  return { fields, body: lines.slice(end + 1), bodyLine: end + 2, problems };

/** A one-line YAML scalar: quoted (`"..."` with `\"` and `\\`, or `'...'` with `''`) or plain. */
function scalar(v, line, problems) {
  if (v.startsWith('"')) {
    const m = /^"((?:[^"\\]|\\.)*)"$/.exec(v);
    if (m) return m[1].replace(/\\(.)/g, "$1");
  } else if (v.startsWith("'")) {
    const m = /^'((?:[^']|'')*)'$/.exec(v);
    if (m) return m[1].replaceAll("''", "'");
  } else if (/^[|>[{&*!%@`]/.test(v)) {
    problems.push(`line ${line}: a value starting with "${v[0]}" is YAML syntax this check does not read; write one quoted line`);
    return v;
  } else if (/: |\s#/.test(v) || v.endsWith(":")) {
    problems.push(`line ${line}: a plain value with ": " or " #" is not what it seems in YAML; quote it`);
    return v;
  } else return v;
  problems.push(`line ${line}: an unterminated or malformed quoted value`);
  return v;
}

/** GitHub's anchor for the heading text `raw` (before de-duplication). */
export function slug(raw) {
  const text = raw.replace(/!?\[([^\]]*)\]\([^)]*\)/g, "$1");
  return text.toLowerCase().replace(/[^\p{L}\p{M}\p{N}\p{Pc} -]/gu, "").replace(/ /g, "-");

export function scan(lines, first = 1) {
  const anchors = new Set();
  const seen = new Map();
  const links = [];
  const spans = [];
  let fence = null;
  lines.forEach((raw, i) => {
    const line = first + i;
    const f = FENCE.exec(raw);
    if (fence) {
      if (f && f[1][0] === fence[0] && f[1].length >= fence.length && raw.trim() === f[1]) fence = null;
      return;
    }
    if (f) {
      fence = f[1];
      return;
    }
    const plain = raw.replace(/(`+)(?!`)(.+?)(?<!`)\1(?!`)/g, (_, _ticks, code) => {
      spans.push({ line, value: code.trim() });
      return " ";
    });
    const h = /^ {0,3}#{1,6}[ \t]+(.*?)(?:[ \t]+#+)?[ \t]*$/.exec(raw);
    if (h) {
      const base = slug(h[1]);
      const n = seen.get(base) ?? 0;
      seen.set(base, n + 1);
      anchors.add(n === 0 ? base : `${base}-${n}`);
    }
    for (const m of plain.matchAll(/!?\[[^\]]*\]\(\s*(<[^>]*>|[^)\s]+)(?:\s+"[^"]*")?\s*\)/g)) {
      links.push({ line, value: m[1].replace(/^<|>$/g, "") });
    }
    const def = /^ {0,3}\[[^\]]+\]:\s*(\S+)/.exec(plain);
    if (def) links.push({ line, value: def[1].replace(/^<|>$/g, "") });
  });
  return { anchors, links, spans, unclosed: fence !== null };

// What it does not do: see a spelling it does not list in JavaScript (a computed property name, an alias of `require`,
// `process.binding` through a variable), or Rust written by a macro or with a comment inside a path (`std::/* */process`).
// Timeouts are scanned for in JavaScript only (`setTimeout`, `AbortSignal.timeout`, `timers/promises`, ...): in Rust the
// binding has timers of its own for its housekeeping (exec.rs), and no spelling tells those from a process timeout, so
// that is for review. index.js is under ~200 lines by W13's card; review reads it once. A source it cannot read exits 2,
// never 0.

const NODE = "bindings/node";
const JS_DENIED = [
  "child_process", "process.kill", ".kill(", "setTimeout", "setInterval", "AbortSignal.timeout",
  "Bun.spawn", "Bun.$", "Deno.Command", "Deno.run", "Deno.kill", "process.binding", "internalBinding",
  "cluster", "timers/promises", "scheduler.wait", "getBuiltinModule",
];
/** A `require(` or `import(` whose argument is not a string literal: it could load anything, and is not read. */
const JS_COMPUTED = /\b(?:require|import)\s*\(\s*(?!["'])/;
const JS_LOCAL = /(?:require\(\s*|\bfrom\s+|\bimport\(\s*)["'`]\.{1,2}\//;
const RUST_DENIED = ["tokio::process", "libc", "nix::", "windows_sys", ".kill(", "run_script"];
const ALLOWED_DEPS = { normal: ["hugr-omni", "napi", "napi-derive"], build: ["napi-build"] };

/** The dependencies of the binding crate, as cargo reads them: `{ name, kind }`, `name` the real package (not a rename). */
function dependencies(root) {
  const manifest = join(root, NODE, "Cargo.toml");
  read(root, `${NODE}/Cargo.toml`);
  const r = spawnSync("cargo", ["metadata", "--no-deps", "--offline", "--format-version", "1", "--manifest-path", manifest], {
    encoding: "utf8", cwd: root, maxBuffer: 256 * 1024 * 1024,
  });
  if (r.error) throw new Unreadable(`${NODE}/Cargo.toml: cargo cannot be started to read it (${r.error.code ?? r.error.message})`);
  if (r.status !== 0) throw new Unreadable(`${NODE}/Cargo.toml: cargo cannot read it:\n${r.stderr.trim().split("\n").slice(-6).join("\n")}`);
  let meta;
  try {
    meta = JSON.parse(r.stdout);
  } catch {
    throw new Unreadable(`${NODE}/Cargo.toml: cargo metadata did not answer JSON`);
  }
  const real = realpathSync(manifest);
  const pkg = (meta.packages ?? []).find((p) => realpathSync(p.manifest_path) === real);
  if (!pkg) throw new Unreadable(`${NODE}/Cargo.toml: cargo metadata does not list the binding package`);
  return pkg.dependencies.filter((d) => d.kind !== "dev").map((d) => ({ name: d.name, kind: d.kind ?? "normal" }));

const js = read(root, `${NODE}/index.js`);
scanRaw(`${NODE}/index.js`, js, JS_DENIED);
js.split("\n").forEach((line, i) => {
  if (JS_LOCAL.test(line)) out.push(`${NODE}/index.js:${i + 1}: loads another local file, which this check does not read`);
  if (JS_COMPUTED.test(line)) out.push(`${NODE}/index.js:${i + 1}: a require() or import() whose argument is not a string literal loads a file this check cannot name`);
});
const { rust, other } = listing(root, `${NODE}/src`);
if (rust.length === 0) throw new Unreadable(`${NODE}/src: no .rs file found (the scan came back EMPTY)`);
for (const f of rust) scanRust(f, read(root, f));
for (const f of other) out.push(`${f}: a file in the binding's sources that is not .rs; this check does not read it`);
try {
  scanRust(`${NODE}/build.rs`, read(root, `${NODE}/build.rs`));
} catch (e) {
  if (!(e instanceof Unreadable) || !/ENOENT/.test(e.message)) throw e; // a binding without a build script is fine
}
const deps = dependencies(root);
if (deps.length === 0) throw new Unreadable(`${NODE}/Cargo.toml: no dependency found (the manifest came back EMPTY)`);
for (const { name, kind } of deps) {
  if (!ALLOWED_DEPS[kind]?.includes(name)) out.push(`${NODE}/Cargo.toml: ${kind} dependency \`${name}\` is not one of ${(ALLOWED_DEPS[kind] ?? []).join(", ") || "(none)"}`);
}

// The surface is every exported function, interface, class and type alias, each member of an interface or class,
// and each member of a `{ ... }` type literal anywhere inside them, named by its path: `run`, `Child`, `Child.stop`,
// `Child.stop.graceMs`, `PtyOption.cols`. Parameter names are not items (they are positional); string-literal union
// values are not items either (they are values, not capabilities).
//
// Anything outside that grammar (a declaration that is not exported, an index signature, a template literal type)
// is `Unreadable`, never skipped: a surface that a reader silently half-understood is the failure this guards against.

/** The repository root of a check script (shared by parity.mjs and binding.mjs): `--root <dir>` or `fallback`; any other argument is `Unreadable`, never ignored. */
export function rootArg(argv, fallback) {
  const args = argv.slice(2);
  if (args.length === 0) return fallback;
  if (args.length === 2 && args[0] === "--root" && args[1] !== "" && !args[1].startsWith("--")) return resolve(args[1]);
  throw new Unreadable(`unknown or incomplete arguments: ${args.join(" ")} (the only one is --root <dir>)`);

/** The members of a `{ ... }` whose `{` was just consumed; consumes the closing `}`. */
function members(path) {
  while (!at("}")) {
    if (at(";") || at(",")) {
      p++;
      continue;
    }
    if (toks[p]?.k === "id" && toks[p].v === "readonly") p++;
    const t = toks[p];
    if (t?.k !== "id" && t?.k !== "str") fail("unsupported member (an index, call or construct signature?)");
    p++;
    if (at("?")) p++;
    if (!at(":") && !at("(")) fail(`unsupported member syntax after '${t.v}'`);
    const full = [...path, t.v];
    items.add(full.join("."));
    body(full, true);
  }
  p++;
}

while (p < toks.length) {
  if (toks[p].k !== "id" || toks[p].v !== "export") fail("every top-level declaration must start with `export`");
  p++;
  const kind = word();
  if (kind === "function") {
    const name = word();
    items.add(name);
    body([name], false);
  } else if (kind === "interface" || kind === "class") {
    const name = word();
    items.add(name);
    while (!at("{")) {
      if (p >= toks.length) fail(`${kind} ${name} has no body`);
      p++;
    }
    p++;
    members([name]);
  } else if (kind === "type") {
    const name = word();
    items.add(name);
    if (!at("=")) fail(`type ${name} has no \`=\``);
    p++;
    body([name], false);
  } else {
    fail(`unsupported declaration \`export ${kind}\``);
  }
}
if (items.size === 0) throw new Unreadable(`${file}: no exported declaration found (the surface came back EMPTY)`);

// v0.1 covers TypeScript and Rust. Python (C-PAR-01 is v0.2) is not read here: its column joins the map with the
// package. Declared limit: the capabilities are compared, not the values inside a type: a Rust enum variant or a TypeScript
// string-literal value (an error code, a `reason`) that exists in one language only is not caught (v0.2). A check that cannot read its input exits 2 and says which file and why, never 0.
//
//   node scripts/surface-check/parity.mjs [--root <repository root>]
// Exit: 0 parity holds · 1 violations (each names the item) · 2 an input cannot be read.

/** One language's side: every public item placed once, every placed item real, no excluded word. */
function sideViolations(lang, surface, placed, excluded, out) {
  const owner = new Map();
  for (const [concept, items] of placed) {
    for (const item of items) {
      if (owner.has(item)) out.push(`${lang} item \`${item}\` is placed in two concepts (${owner.get(item)} and ${concept})`);
      owner.set(item, concept);
    }
  }
  const real = new Set(surface);
  for (const item of surface) {
    if (!owner.has(item)) out.push(`${lang} public item \`${item}\` is in no concept of scripts/surface-check/parity.txt (a capability added to one language: INV-02)`);
  }
  for (const [item, concept] of owner) {
    if (!real.has(item)) out.push(`parity.txt places \`${item}\` under "${concept}" but the ${lang} surface has no such item`);
  }
  for (const item of surface) {
    const hit = words(last(item)).find((w) => excluded.has(w));
    if (hit) out.push(`${lang} public item \`${item}\` carries the excluded word "${hit}" (${excluded.get(hit)})`);
  }

if (concepts.length > MAX_CONCEPTS) out.push(`the glossary has ${concepts.length} concepts; the limit is ${MAX_CONCEPTS}`);
if (declared !== undefined && declared !== concepts.length) {
  out.push(`the glossary heading says ${declared} concepts but lists ${concepts.length}`);
}
for (const { name } of concepts) {
  const hit = words(name).find((w) => excluded.has(w));
  if (hit) out.push(`glossary concept "${name}" carries the excluded word "${hit}" (${excluded.get(hit)})`);
}

const byConcept = new Map();
for (const row of rows) {
  if (byConcept.has(row.concept)) out.push(`parity.txt has two rows for "${row.concept}"`);
  byConcept.set(row.concept, row);
  if (!concepts.some((c) => c.name === row.concept)) out.push(`parity.txt row "${row.concept}" is not a glossary concept`);
}
for (const { name, names, parenthetical } of concepts) {
  if (parenthetical && names.length === 0) out.push(`glossary concept "${name}" has a parenthetical that cites no \`backticked\` name, so nothing is cross-checked against it`);
  const row = byConcept.get(name);
  if (!row) {
    out.push(`glossary concept "${name}" has no row in parity.txt`);
    continue;
  }
  if (row.ts.length === 0) out.push(`concept "${name}" has no TypeScript item`);
  if (row.rust.length === 0) out.push(`concept "${name}" has no Rust item`);
  for (const cited of names) {
    if (!row.ts.some((item) => last(item) === cited)) out.push(`the glossary cites \`${cited}\` under "${name}" but no TypeScript item of that concept is named so`);
  }
}
sideViolations("TypeScript", ts, new Map(rows.map((r) => [r.concept, r.ts])), excluded, out);
sideViolations("Rust", rust.items, new Map(rows.map((r) => [r.concept, r.rust])), excluded, out);

const summary =
  `glossary ${concepts.length} concepts (limit ${MAX_CONCEPTS}) · TypeScript ${ts.length} items, Rust ${rust.items.length} items` +
  ` (${rust.foreign.length} re-exported from another crate: ${rust.foreign.join(", ") || "none"}) · excluded words: ${[...excluded.keys()].join(", ")}` +
  " · Python: v0.2, not read";

// This is a line reader, not a Rust parser, and it says so: it relies on the layout `cargo fmt --check` enforces in CI
// (items at column 0, members at 4 spaces, a block closed by `}` at column 0). It does not expand macros, follow
// `cfg`, or see trait impls (`impl Trait for T` is not an inherent impl; enum variants are values, not capabilities).
//
// What it understands, it reads. What it does not understand, it refuses: every public syntax outside the list below
// is `Unreadable`, never skipped, so a new public form can only turn this check red until the reader learns it.
//   - column 0 of lib.rs and api/mod.rs: `pub use` (a path, `{a, b}`, no `as`), `#[doc(hidden)] pub mod`, and the one
//     glob `pub use api::*;` in lib.rs; any other `pub ...` line, any other glob, any public module is refused;
//   - an exported name must be defined exactly once as a `pub struct` or `pub enum` of this crate (or come from another
//     crate); a tuple struct with a public field, a struct body that cannot be found, is refused;
//   - an inherent impl of an exported type, at column 0, written `impl T`, `impl<..> T<..>` or through a path
//     (`impl crate::api::T`: the last segment names the type): each `    pub fn` (with `const`/`async`/`unsafe`) is a
//     method; any other `    pub ...` line (`pub extern "C" fn`, `pub const`, `pub type`) is refused; an impl of an
//     exported type nested inside a fn or mod, an impl header of another shape that mentions one, and a module-level
//     alias of one (`type X = T;`, which an `impl X` would hide) are refused;
//   - `#[macro_export]` and any `macro_rules!` in the crate are refused (a macro can write public API this reader
//     cannot expand), and so are `include!`/`include_str!`/`include_bytes!` and `#[path = ...]`, which pull in code
//     this reader would not see; a file under src that is not `.rs` is refused for the same reason (a module could
//     include it). Test modules are skipped only when their `mod x;` carries `#[cfg(test)]`; any other module file,
//     whatever its name, is part of the library and is read.
//
// Declared limit (C-PAR-01 is v0.2 for the rest): what the reader compares is the capabilities, items named `Type`,
// `Type.field` and `Type::method`. Enum variants here and string-literal union values in index.d.ts (error codes,
// `reason`, `stream`) are values: they are not compared across languages, so a code that exists in one language only
// is not caught.

export function rustSurface(root) {
  const exported = [
    ...reexports(read(join(root, SRC, "lib.rs")), `${SRC}/lib.rs`),
    ...reexports(read(join(root, SRC, "api/mod.rs")), `${SRC}/api/mod.rs`),
  ];
  const listed = sources(root, SRC);
  const everything = listed.rs.map((f) => ({ f, lines: read(join(root, f)).split("\n") }));
  const isTest = testModules(everything);
  const strange = listed.other.find((f) => !isTest(f));
  if (strange) throw new Unreadable(`${strange}: a file under src that is not .rs; a module could include it and this reader would not see it`);
  const files = everything.filter(({ f }) => !isTest(f));
  for (const { f, lines } of files) {
    const pulled = lines.findIndex((l) => /\binclude(?:_str|_bytes)?!\s*[(\[{]/.test(l) || /#\s*\[\s*(?:cfg_attr\s*\([^\]]*?)?\bpath\s*=/.test(l));
    if (pulled >= 0) throw new Unreadable(`${f}:${pulled + 1}: \`${lines[pulled].trim().slice(0, 60)}\` pulls in code this reader does not see (include! and #[path] are refused)`);
    const at = lines.findIndex((l) => l.includes("#[macro_export]"));
    if (at >= 0) throw new Unreadable(`${f}:${at + 1}: an exported macro is public API this reader cannot name`);
    const rules = lines.findIndex((l) => /^\s*macro_rules!/.test(l));
    if (rules >= 0) throw new Unreadable(`${f}:${rules + 1}: a macro_rules! can write impls this reader cannot expand`);

for (const name of names) {
  const def = new RegExp(`^pub (struct|enum|union|trait|type|fn|const|static) ${name}\\b`);
  const found = files.flatMap(({ f, lines }) => lines.flatMap((l, i) => (def.test(l) ? [{ f, lines, i, kind: def.exec(l)[1] }] : [])));
  if (found.length !== 1) {
    const where = found.map(({ f, i }) => `${f}:${i + 1}`).join(", ");
    throw new Unreadable(`${SRC}: \`${name}\` is exported but ${found.length === 0 ? "defined nowhere" : `defined ${found.length} times (${where})`}`);
  }
  const { f, lines, i, kind } = found[0];
  if (kind !== "struct" && kind !== "enum") throw new Unreadable(`${f}:${i + 1}: \`${name}\` is a ${kind}; this reader maps structs and enums`);
  if (kind === "struct") {
    if (lines[i].endsWith("{")) {
      for (const [j, l] of body(lines, i, f)) {
        const field = /^ {4}pub (\w+):/.exec(l);
        if (field) items.add(`${name}.${field[1]}`);
        else if (publicMember(l)) throw new Unreadable(`${f}:${j + 1}: \`${l.trim()}\` is public syntax this reader does not understand in struct ${name}`);
      }
    } else if (lines[i].includes("(")) {
      if (/\bpub\b/.test(lines[i].slice(lines[i].indexOf("(")))) throw new Unreadable(`${f}:${i + 1}: tuple struct ${name} has a public field; not supported`);
    } else if (!lines[i].endsWith(";")) {
      throw new Unreadable(`${f}:${i + 1}: cannot find the body of struct ${name}`);
    }
  }
}
const alias = new RegExp(`^(?:pub(?:\\([^)]*\\))?\\s+)?type\\s+\\w+(?:<[^>]*>)?\\s*=\\s*(?:\\w+::)*(${[...names].join("|")})(?:<[^>]*>)?\\s*;`);
for (const { f, lines } of files) {
  const at = lines.findIndex((l) => names.size > 0 && alias.test(l));
  if (at >= 0) throw new Unreadable(`${f}:${at + 1}: \`${lines[at].trim()}\` aliases an exported type; an \`impl\` of the alias would hide its methods from this reader`);

for (const { f, lines } of files) {
  lines.forEach((l, i) => {
    if (!/^\s*impl[\s<]/.test(l)) return;
    let end = i;
    while (end < lines.length && !lines[end].endsWith("{")) end++;
    const header = lines.slice(i, end + 1).join(" ");
    if (/\sfor\s/.test(header)) return; // a trait impl
    const target = implTarget(header);
    if (target === null) {
      if ([...names].some((n) => new RegExp(`\\b${n}\\b`).test(header))) throw new Unreadable(`${f}:${i + 1}: cannot read the impl header \`${header.trim().slice(0, 60)}\``);
      return;
    }
    if (!names.has(target)) return; // an impl of some other type that merely mentions an exported one
    if (/^\s/.test(l)) throw new Unreadable(`${f}:${i + 1}: an impl of ${target} nested inside a fn or mod is not read; move it to column 0`);
    for (const [j, member] of body(lines, end, f)) {
      const fn = /^ {4}pub (?:(?:const|async|unsafe) )*fn (\w+)/.exec(member);
      if (fn) items.add(`${target}::${fn[1]}`);
      else if (publicMember(member)) throw new Unreadable(`${f}:${j + 1}: \`${member.trim()}\` is public syntax this reader does not understand in impl ${target}`);
    }
  });
}
if (names.size === 0) throw new Unreadable(`${SRC}: no \`pub use\` re-export found (the surface came back EMPTY)`);
return { items: [...items].sort(), foreign };

