test("parity: a method added through a qualified impl is seen; one the reader cannot place is refused", () => {
  const append = (text) => ({ "crates/hugr-omni/src/api/command.rs": (t) => `${t}
${text}
` });
  expects(parity(append("impl crate::api::Command {
    pub fn shell(&self) {}
}")), 1, "`Command::shell`");
  expects(parity(append("impl api::Command {
    pub fn shell(&self) {}
}")), 1, "`Command::shell`");
  expects(parity(append("impl<T> crate::api::Command<T> {
    pub fn extra(&self) {}
}")), 1, "`Command::extra`");
  expects(parity(append("fn helper() {
    impl Command {
        pub fn shell(&self) {}
    }
}")), 2, "nested inside a fn or mod");
  expects(parity(append("mod inner {
    impl super::Command {
        pub fn shell(&self) {}
    }
}")), 2, "nested inside a fn or mod");
  expects(parity(append("impl<T> <Command as Other>::Out {
    pub fn shell(&self) {}
}")), 2, "cannot read the impl header");
  expects(parity(append("type Cmd = Command;

impl Cmd {
    pub fn shell(&self) {}
}")), 2, "aliases an exported type");
  expects(parity(append("type Cmd = crate::api::Command;")), 2, "aliases an exported type");
  expects(parity(append("macro_rules! add {
    () => {};
}")), 2, "macro_rules!");
  expects(parity(append("impl Drop for Command {
    fn drop(&mut self) {}
}

impl<T> From<T> for Command {
    fn from(_t: T) -> Command {
        Command::new()
    }
}")), 0);
});

test("parity: code pulled in by include!, #[path] or a non-.rs file is refused, since the reader would not see it", () => {
  const append = (text) => ({ "crates/hugr-omni/src/api/command.rs": (t) => `${t}
${text}
` });
  const ext = "impl Command {
    pub fn shell(self) -> Self {
        self
    }
}
";
  expects(parity({ ...append('include!("command_ext.in");'), "crates/hugr-omni/src/api/command_ext.in": ext }), 2, "command_ext.in", "not .rs");
  expects(parity(append('include!("command_ext.rs");')), 2, "pulls in code this reader does not see");
  expects(parity(append('const S: &str = include_str!("data.txt");')), 2, "include! and #[path] are refused");
  expects(parity(append('include_bytes!("data.bin");')), 2, "pulls in code");
  expects(parity(append('#[path = "elsewhere.rs"]
mod elsewhere;')), 2, "#[path]");
  expects(parity(append('#[cfg_attr(unix, path = "unix.rs")]
mod platform;')), 2, "#[path]");
  expects(parity({ "crates/hugr-omni/src/api/notes.md": "# a note
" }), 2, "notes.md", "not .rs");
  expects(parity(append('fn helper() {
    let _path = "x";
}')), 0);
});

